package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.memory.*; import net.fabricmc.fabric.api.entity.FakePlayer; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.entity.npc.villager.Villager;
public final class VillagerConversationGameTest { @GameTest public void directTalkCreatesMemory(GameTestHelper c){Villager v=c.spawn(EntityTypes.VILLAGER,2,1,2);var p=FakePlayer.get(c.getLevel());p.setPos(3,1,2);c.runAtTickTime(1,()->{TheWorldRemembers.talkToVillager(p,v,MemoryManager.get(c.getLevel().getServer()));if(MemoryManager.get(c.getLevel().getServer()).memoriesOf(v.getUUID()).stream().noneMatch(m->m.type()==MemoryEventType.PLAYER_TALKED&&m.playerId().equals(p.getUUID()))){c.fail("Direct conversation did not create memory");return;}c.succeed();});}}
